INSERT INTO site_content (content_key, content_value) VALUES ('brand', '{"name": "Akagera Inc", "tagline": "Technology solutions built for what comes next.", "primary_color": "#BD4A39", "ink": "#141414", "paper": "#FFFFFF", "logo": "/assets/inc.png"}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('hero', '{"kicker": "Akagera Inc \\u2014 Software Solutions", "title": "Technology Solutions Built for What Comes Next.", "subtitle": "Akagera Inc builds mobile apps, websites, desktop software, SaaS products, and custom digital solutions that help individuals, businesses, and organizations turn ideas into reliable technology.", "primary_cta": {"label": "Explore Our Solutions", "url": "/solutions"}, "secondary_cta": {"label": "Start a Project", "url": "/contact?intent=project"}}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('homepage_sections', '[{"key": "hero", "label": "Hero", "enabled": true, "order": 1}, {"key": "product_grid", "label": "Software built by Akagera Inc", "enabled": true, "order": 2}, {"key": "featured_products", "label": "Featured Akagera Products", "enabled": true, "order": 3}, {"key": "services", "label": "Services", "enabled": true, "order": 4}, {"key": "industries", "label": "Industries", "enabled": true, "order": 5}, {"key": "stats", "label": "Statistics", "enabled": true, "order": 6}, {"key": "case_studies", "label": "Our Work", "enabled": true, "order": 7}, {"key": "testimonials", "label": "Testimonials", "enabled": true, "order": 8}, {"key": "blog", "label": "From the blog", "enabled": true, "order": 9}, {"key": "cta", "label": "Call to action", "enabled": true, "order": 10}, {"key": "location", "label": "Our location", "enabled": true, "order": 11}]') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('product_categories', '[{"name": "Mobile Applications", "slug": "mobile", "icon": "smartphone", "description": "Apps built for Android and iOS.", "platforms": ["android", "ios"]}, {"name": "Web Applications", "slug": "web", "icon": "globe", "description": "Modern responsive web platforms.", "platforms": ["web"]}, {"name": "Windows Software", "slug": "windows", "icon": "monitor", "description": "Native, professional Windows applications.", "platforms": ["windows"]}, {"name": "macOS Software", "slug": "macos", "icon": "command", "description": "Software designed for Apple''s desktop ecosystem.", "platforms": ["macos"]}, {"name": "SaaS Platforms", "slug": "saas", "icon": "cloud", "description": "Cloud-based software available through subscriptions.", "platforms": ["cloud"]}, {"name": "Custom Software", "slug": "custom", "icon": "layers", "description": "Software designed specifically for organizations and businesses.", "platforms": []}]') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('social_links', '{"linkedin": "https://www.linkedin.com/company/akagera-inc", "github": "https://github.com/akagerainc-boop", "x": "https://x.com/akagerainc", "facebook": "https://www.facebook.com/akagerainc", "instagram": "https://www.instagram.com/akagerainc", "youtube": "https://www.youtube.com/@akagerainc"}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('contact_info', '{"email": "akagerainc@gmail.com", "support_email": "support@akagerainc.store", "sales_email": "sales@akagerainc.store", "phone": "+250 795 226 123", "whatsapp": "250795226123", "address_lines": ["Innovation Hub Building", "Main Street, Musanze District", "Northern Province, Rwanda"], "hours": ["Monday - Friday: 8:00 AM - 6:00 PM", "Saturday: 9:00 AM - 1:00 PM", "Sunday: Closed"], "map_query": "Musanze,Rwanda"}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('company_info', '{"who_we_are": "Akagera Inc is a technology and software solutions company. We design, build, and maintain software across mobile, web, desktop, and cloud \\u2014 for individuals, businesses, and organizations.", "mission": "To create useful, scalable, and reliable technology that helps people and organizations do more.", "vision": "A connected Africa where every organization runs on software it can trust.", "values": ["Reliability", "Craft", "Transparency", "Long-term thinking", "Customer obsession"], "founded": "2021", "headquarters": "Musanze, Rwanda"}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('whatsapp', '{"number": "250795226123", "message": "Hello Akagera Inc, I''d like to talk about a project."}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('pricing', '[{"name": "Starter", "price": "$49", "currency": "USD", "duration": "30-day service", "popular": false, "description": "For a focused piece of work with a clear scope.", "features": ["Basic support", "1 project", "30-day delivery window", "Source handover"]}, {"name": "Professional", "price": "$199", "currency": "USD", "duration": "90-day service", "popular": true, "description": "For growing teams that need more surface area and priority help.", "features": ["Priority support", "Multiple features", "Priority assistance", "2 revision rounds", "Deployment"]}, {"name": "Enterprise", "price": "Custom", "currency": "USD", "duration": "Ongoing", "popular": false, "description": "For organizations needing dedicated delivery and SLAs.", "features": ["Dedicated team", "Advanced security", "SLA", "API integration", "Onboarding & training"]}]') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('seo_defaults', '{"title": "Akagera Inc \\u2014 Software Solutions", "description": "Akagera Inc builds software, sells digital products and services, publishes applications, and provides licenses, subscriptions, and professional technology solutions.", "og_image": "/assets/inc.png", "site_url": "https://akagerainc.store"}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('industries_intro', '{"title": "Industry solutions", "subtitle": "Software patterns we''ve shipped across sectors."}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('legal_privacy', '{"title": "Privacy Policy", "updated": "2026-01-01", "body": "Akagera Inc collects only the information needed to deliver its products and services. We never sell your data. Contact privacy@akagerainc.store for requests."}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('legal_terms', '{"title": "Terms of Service", "updated": "2026-01-01", "body": "By using this website and its services you agree to Akagera Inc''s terms. Services are delivered according to the scope and duration shown at purchase."}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('legal_refund', '{"title": "Refund Policy", "updated": "2026-01-01", "body": "Digital services may be refunded within 14 days if work has not started. Licenses and subscriptions are refundable within 14 days if unused."}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
INSERT INTO site_content (content_key, content_value) VALUES ('legal_cookie', '{"title": "Cookie Policy", "updated": "2026-01-01", "body": "We use essential cookies for authentication and a minimal set of analytics cookies. You can decline non-essential cookies."}') ON DUPLICATE KEY UPDATE content_value = VALUES(content_value);
